import { timingSafeEqual } from 'node:crypto'
import type { NextRequest } from 'next/server'
export async function POST(request: NextRequest) {
  const auth = request.headers.get('authorization') ?? ''
  const expected = `Bearer ${process.env.INGEST_TOKEN ?? ''}`
  const a = Buffer.from(auth), b = Buffer.from(expected)
  if (!process.env.INGEST_TOKEN || a.length !== b.length || !timingSafeEqual(a, b))
    return Response.json({ error: 'unauthorized' }, { status: 401 })
  const body = await request.json() // validate shape + enforce your own size cap; Route Handlers have no built-in body limit
